"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[44108],{3331:(e,s,t)=>{t.d(s,{R:()=>a,x:()=>o});var n=t(36672);const i={},r=n.createContext(i);function a(e){const s=n.useContext(r);return n.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),n.createElement(r.Provider,{value:s},e.children)}},79748:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>a,metadata:()=>n,toc:()=>u});const n=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"Construire GitHub avec Ruby on Rails","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/fr/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8 avril 2023","top_news":"Construire GitHub avec Ruby on Rails"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/fr/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/fr/2023/04/07"}}');var i=t(23420),r=t(3331);const a={localized_date:"8 avril 2023",top_news:"Construire GitHub avec Ruby on Rails"},o="2023-04-08",l={},u=[{value:"Construire GitHub avec Ruby on Rails",id:"construire-github-avec-ruby-on-rails",level:2},{value:"Ask Wirecutter : Pouvez-vous me recommander une t\xe9l\xe9vision non intelligente ?",id:"ask-wirecutter--pouvez-vous-me-recommander-une-t\xe9l\xe9vision-non-intelligente-",level:2},{value:"Codeberg - Une alternative open source rapide \xe0 GitHub",id:"codeberg---une-alternative-open-source-rapide-\xe0-github",level:2},{value:"Riz p\xe9renne : Planter une fois, r\xe9colter encore et encore",id:"riz-p\xe9renne--planter-une-fois-r\xe9colter-encore-et-encore",level:2},{value:"60 millions d&#39;Am\xe9ricains ont des imp\xf4ts si simples que le fisc pourrait les faire automatiquement.",id:"60-millions-dam\xe9ricains-ont-des-imp\xf4ts-si-simples-que-le-fisc-pourrait-les-faire-automatiquement",level:2},{value:"Nous devons dire aux gens que ChatGPT leur mentira, et non pas d\xe9battre de linguistique.",id:"nous-devons-dire-aux-gens-que-chatgpt-leur-mentira-et-non-pas-d\xe9battre-de-linguistique",level:2},{value:"Twitter ne permet pas de retweeter les tweets qui renvoient \xe0 Substack",id:"twitter-ne-permet-pas-de-retweeter-les-tweets-qui-renvoient-\xe0-substack",level:2},{value:"Les services cloud de Western Digital en panne depuis 4 jours",id:"les-services-cloud-de-western-digital-en-panne-depuis-4-jours",level:2},{value:"Comment fonctionne le sharding des bases de donn\xe9es ?",id:"comment-fonctionne-le-sharding-des-bases-de-donn\xe9es-",level:2},{value:"Hubble voit un possible trou noir en fuite cr\xe9ant une tra\xeen\xe9e d&#39;\xe9toiles",id:"hubble-voit-un-possible-trou-noir-en-fuite-cr\xe9ant-une-tra\xeen\xe9e-d\xe9toiles",level:2},{value:"La plus grande violation de donn\xe9es en Nouvelle-Z\xe9lande montre que la r\xe9tention est le g\xe9ant endormi de la s\xe9curit\xe9 des donn\xe9es.",id:"la-plus-grande-violation-de-donn\xe9es-en-nouvelle-z\xe9lande-montre-que-la-r\xe9tention-est-le-g\xe9ant-endormi-de-la-s\xe9curit\xe9-des-donn\xe9es",level:2},{value:"Les \xc9tats-Unis et la Chine se livrent une guerre sous les vagues \xe0 propos des c\xe2bles internet",id:"les-\xe9tats-unis-et-la-chine-se-livrent-une-guerre-sous-les-vagues-\xe0-propos-des-c\xe2bles-internet",level:2},{value:"Le &quot;sharding&quot; des bases de donn\xe9es vient d&#39;Ultima Online ?",id:"le-sharding-des-bases-de-donn\xe9es-vient-dultima-online-",level:2},{value:"Pourquoi Phreesia a-t-elle partag\xe9 mes donn\xe9es m\xe9dicales alors que je m&#39;\xe9tais d\xe9sengag\xe9 ?",id:"pourquoi-phreesia-a-t-elle-partag\xe9-mes-donn\xe9es-m\xe9dicales-alors-que-je-m\xe9tais-d\xe9sengag\xe9-",level:2},{value:"JavaScript-algorithmes : Algorithmes et structures de donn\xe9es impl\xe9ment\xe9s en JavaScript",id:"javascript-algorithmes--algorithmes-et-structures-de-donn\xe9es-impl\xe9ment\xe9s-en-javascript",level:2},{value:"SpaceX se rapproche du premier lancement de Starship Super Heavy",id:"spacex-se-rapproche-du-premier-lancement-de-starship-super-heavy",level:2},{value:"Show Discussion Service : Construire des synth\xe9tiseurs musicaux avec des requ\xeates SQL",id:"show-discussion-service--construire-des-synth\xe9tiseurs-musicaux-avec-des-requ\xeates-sql",level:2},{value:"La plus longue ligne droite en Grande-Bretagne sans traverser de route publique",id:"la-plus-longue-ligne-droite-en-grande-bretagne-sans-traverser-de-route-publique",level:2},{value:"Flipper Zero interdit par Amazon car il s&#39;agit d&#39;un &quot;dispositif d&#39;\xe9cr\xe9mage de cartes&quot;.",id:"flipper-zero-interdit-par-amazon-car-il-sagit-dun-dispositif-d\xe9cr\xe9mage-de-cartes",level:2},{value:"Reverse Engineering de l&#39;API de Facebook Messenger",id:"reverse-engineering-de-lapi-de-facebook-messenger",level:2},{value:"Les machines de Tatjana van Vark",id:"les-machines-de-tatjana-van-vark",level:2},{value:"Big Ball of Mud (1999)",id:"big-ball-of-mud-1999",level:2},{value:"Yann LeCun et Andrew Ng : Pourquoi la pause de 6 mois sur l&#39;IA est une mauvaise id\xe9e [vid\xe9o]",id:"yann-lecun-et-andrew-ng--pourquoi-la-pause-de-6-mois-sur-lia-est-une-mauvaise-id\xe9e-vid\xe9o",level:2},{value:"La NSA a cr\xe9\xe9 un cours de cybers\xe9curit\xe9 en ligne avec des centaines de classes",id:"la-nsa-a-cr\xe9\xe9-un-cours-de-cybers\xe9curit\xe9-en-ligne-avec-des-centaines-de-classes",level:2},{value:"Remplacer les mauvais syst\xe8mes par d&#39;autres mauvais syst\xe8mes",id:"remplacer-les-mauvais-syst\xe8mes-par-dautres-mauvais-syst\xe8mes",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Ask Discussion Service : Quelle est votre meilleure ressource pour vous tenir au courant des d\xe9veloppements en mati\xe8re d&#39;IA ?",id:"ask-discussion-service--quelle-est-votre-meilleure-ressource-pour-vous-tenir-au-courant-des-d\xe9veloppements-en-mati\xe8re-dia-",level:2},{value:"Preuve directe de l&#39;utilisation de drogues multiples \xe0 l&#39;\xe2ge du bronze \xe0 partir d&#39;un test sur des cheveux humains",id:"preuve-directe-de-lutilisation-de-drogues-multiples-\xe0-l\xe2ge-du-bronze-\xe0-partir-dun-test-sur-des-cheveux-humains",level:2},{value:"Des officiers de la police de New York se vantent de faire des heures suppl\xe9mentaires dans un enregistrement accidentel",id:"des-officiers-de-la-police-de-new-york-se-vantent-de-faire-des-heures-suppl\xe9mentaires-dans-un-enregistrement-accidentel",level:2},{value:"Show Discussion Service : ChatGDB - GPT-Powered GDB Assistant",id:"show-discussion-service--chatgdb---gpt-powered-gdb-assistant",level:2}];function d(e){const s={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(s.header,{children:(0,i.jsx)(s.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,i.jsx)(s.h2,{id:"construire-github-avec-ruby-on-rails",children:"Construire GitHub avec Ruby on Rails"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Original"}),".\nGitHub.com est \xe9crit en utilisant Ruby on Rails et maintenu par plus d'un millier d'ing\xe9nieurs avec pr\xe8s de 2 millions de lignes de code. La soci\xe9t\xe9 met \xe0 jour le dernier commit Rails chaque semaine avec des demandes d'extraction et des r\xe9visions. Les avantages de ces mises \xe0 jour comprennent une meilleure gestion des connexions \xe0 la base de donn\xe9es et un rendu plus rapide des vues, une s\xe9curit\xe9 am\xe9lior\xe9e et un risque r\xe9duit de probl\xe8mes inconnus. Les tests des derni\xe8res versions identifient et corrigent les probl\xe8mes avant la publication. Le message est une d\xe9claration de confidentialit\xe9 GitHub, contenant des informations sur les caract\xe9ristiques du produit, la s\xe9curit\xe9, les anecdotes, les prix, les ressources, l'API pour les d\xe9veloppeurs, les partenaires, la plateforme et l'assistance. Le message ne semble pas contenir de nouvelles informations ou de nouveaux \xe9v\xe9nements, et la raison pour laquelle il attire l'attention n'est pas claire."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub a reconstruit sa plateforme avec Ruby on Rails, suscitant l'int\xe9r\xeat pour son impact potentiel sur l'\xe9cosyst\xe8me Rails et les exigences en mati\xe8re de couverture des tests. Les utilisateurs soulignent les d\xe9fis li\xe9s \xe0 la ma\xeetrise de Ruby, tels que la couverture de test extr\xeame et le potentiel de d\xe9faillances futures du code. Certains utilisateurs sugg\xe8rent d'utiliser Sorbet pour des types de contr\xf4le plus forts. L'utilisation par GitHub du langage Crystal et du potentiel de m\xe9taprogrammation de Ruby est salu\xe9e, tandis que certains critiquent l'espace de science des donn\xe9es de Ruby. La r\xe9cente mise \xe0 jour de la plateforme Rails de Github par Microsoft, de la version 2.3 \xe0 la version 3, a pos\xe9 des probl\xe8mes, mais le typage statique facilite les mises \xe0 jour. Les d\xe9veloppeurs r\xe9fl\xe9chissent aux compromis entre les tendances technologiques et la stabilit\xe9 \xe9tablie, certains soulignant la facilit\xe9 d'utilisation de Rails mais le retard de la couche de visualisation. Les mises \xe0 jour du framework sont plus efficaces lorsqu'elles sont effectu\xe9es progressivement, avec de bons tests en place. De nombreuses organisations consid\xe8rent que la mise \xe0 jour de l'infrastructure informatique est importante, les capacit\xe9s de test de GitHub sont lou\xe9es et Sorbet est utilis\xe9 par GitHub pour Ruby et Rails."]}),"\n",(0,i.jsx)(s.h2,{id:"ask-wirecutter--pouvez-vous-me-recommander-une-t\xe9l\xe9vision-non-intelligente-",children:"Ask Wirecutter : Pouvez-vous me recommander une t\xe9l\xe9vision non intelligente ?"}),"\n",(0,i.jsxs)(s.p,{children:["(Original) (",(0,i.jsx)(s.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/"}),").\nWirecutter sugg\xe8re de s\xe9curiser les t\xe9l\xe9viseurs intelligents au lieu de trouver des options non intelligentes pour des raisons de confidentialit\xe9. Les t\xe9l\xe9viseurs d\xe9connect\xe9s peuvent \xeatre d\xe9pourvus de fonctions utiles. Les experts conseillent de refuser la collecte de donn\xe9es, de ne se connecter au Wi-Fi que pour les mises \xe0 jour du micrologiciel et de se d\xe9connecter occasionnellement de la lecture en continu. Les vieux t\xe9l\xe9viseurs, les moniteurs 4K ou les projecteurs sont des solutions alternatives. D'autres appareils connect\xe9s \xe0 l'internet posent des probl\xe8mes similaires en mati\xe8re de protection de la vie priv\xe9e."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nUn article traite de la difficult\xe9 de trouver une t\xe9l\xe9vision non intelligente, d\xe9pourvue de fonctions intrusives et inutiles. Les solutions propos\xe9es comprennent l'utilisation d'un t\xe9l\xe9viseur intelligent d\xe9connect\xe9 ou la d\xe9connexion physique des modules pour emp\xeacher les connexions non d\xe9sir\xe9es. La protection de la vie priv\xe9e et l'exfiltration des donn\xe9es suscitent des inqui\xe9tudes. Discussion autour de la consommation d'\xe9nergie, des connexions automatiques potentielles et de la lenteur du processus de d\xe9marrage des t\xe9l\xe9viseurs intelligents par les utilisateurs. Suggestions d'un nom potentiel pour une t\xe9l\xe9vision non intelligente et des caract\xe9ristiques id\xe9ales d'une t\xe9l\xe9vision intelligente. Inqui\xe9tudes concernant le suivi des donn\xe9es et la difficult\xe9 de lancer une entreprise d'\xe9cran muet de haute qualit\xe9. Les utilisateurs discutent des caract\xe9ristiques sp\xe9cifiques des \xe9crans et de la difficult\xe9 de maintenir les t\xe9l\xe9viseurs intelligents d\xe9connect\xe9s. Le comportement contraire \xe0 l'\xe9thique de TCL et les pr\xe9occupations des utilisateurs en mati\xe8re de protection de la vie priv\xe9e sont mis en \xe9vidence."]}),"\n",(0,i.jsx)(s.h2,{id:"codeberg---une-alternative-open-source-rapide-\xe0-github",children:"Codeberg - Une alternative open source rapide \xe0 GitHub"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://codeberg.org/",children:"Original"}),".\nCodeberg.org est une plateforme de collaboration logicielle libre et open-source et un h\xe9bergement Git g\xe9r\xe9 par ses utilisateurs via une organisation \xe0 but non lucratif \xe0 Berlin. La plateforme encourage \xe9galement une communaut\xe9 de cr\xe9ateurs de logiciels libres et de contenus partageant les m\xeames id\xe9es, sans suivi ni vente des donn\xe9es des utilisateurs. Les utilisateurs peuvent s'inscrire et h\xe9berger leurs projets sur le site web, et Codeberg e.V. soutient la communaut\xe9 par des dons et des contributions facultatives. Le site web est accessible en plusieurs langues et les utilisateurs peuvent proposer des contributions pour am\xe9liorer les services de Codeberg."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg fournit une alternative rapide et open-source \xe0 Github qui se concentre sur la collaboration en mati\xe8re de logiciels libres et open-source. Les utilisateurs de Discussion Service se demandent si l'accent mis par Codeberg sur l'\xe9thique des logiciels libres est trop restrictif, tandis que d'autres le louent pour son engagement. En ce qui concerne la nature politique de l'infrastructure informatique, certains affirment que la neutralit\xe9 est impossible mais qu'elle doit \xeatre recherch\xe9e, tandis que d'autres pr\xe9tendent que les opinions politiques sont plus tol\xe9rables dans l'informatique que dans d'autres contextes. Les utilisateurs de Discussion Service discutent \xe9galement de la philosophie de partage des codes, des licences restrictives et de l'impact des codes favorables aux entreprises sur le taux de r\xe9ussite des logiciels libres. Le statut d'organisation \xe0 but non lucratif de Codeberg et son engagement en faveur des licences de logiciels libres sont salu\xe9s. La rapidit\xe9 et la simplicit\xe9 de l'interface de la plateforme sont appr\xe9ci\xe9es, mais des inqui\xe9tudes subsistent quant au respect de la vie priv\xe9e. Certains recommandent Radicle comme alternative aux services centralis\xe9s comme Github."]}),"\n",(0,i.jsx)(s.h2,{id:"riz-p\xe9renne--planter-une-fois-r\xe9colter-encore-et-encore",children:"Riz p\xe9renne : Planter une fois, r\xe9colter encore et encore"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again"}),").\nLes scientifiques ont cr\xe9\xe9 des souches de riz p\xe9rennes qui restent productives et repoussent apr\xe8s chaque r\xe9colte, ce qui se traduit par d'\xe9normes avantages environnementaux, une empreinte carbone plus faible, des sols plus sains et des agriculteurs qui n'ont pas besoin de ressemer. Ces souches, s\xe9lectionn\xe9es au cours des deux derni\xe8res d\xe9cennies, ont \xe9t\xe9 test\xe9es et r\xe9colt\xe9es pendant quatre ann\xe9es cons\xe9cutives par 45 000 petits exploitants pratiquant l'agriculture de subsistance. Selon les experts, si un plus grand nombre d'agriculteurs adoptent ces nouvelles vari\xe9t\xe9s, les avantages pourraient \xeatre consid\xe9rables pour les personnes qui les cultivent, pour l'environnement et pour la population mondiale qui d\xe9pend du riz comme aliment de base."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nLe riz p\xe9renne peut r\xe9duire les \xe9missions de m\xe9thane des rizi\xe8res. La production de b\xe9tail a un impact environnemental important. Le changement climatique entra\xeenera des p\xe9nuries alimentaires et d'autres probl\xe8mes. Le m\xe9thane provenant des rizi\xe8res n'a pas un impact significatif par rapport \xe0 d'autres sources. Le riz p\xe9renne pr\xe9sente des avantages potentiels mais aussi des d\xe9fis. Les experts discutent de l'agriculture et de la production alimentaire. Le succ\xe8s de la riziculture p\xe9renne irrigu\xe9e est mis en \xe9vidence. Les cultures p\xe9rennes permettent d'\xe9conomiser sur les co\xfbts de main-d'\u0153uvre et d'intrants. Les plantes p\xe9rennes pr\xe9sentent des avantages pour le sol et l'extraction des nutriments."]}),"\n",(0,i.jsx)(s.h2,{id:"60-millions-dam\xe9ricains-ont-des-imp\xf4ts-si-simples-que-le-fisc-pourrait-les-faire-automatiquement",children:"60 millions d'Am\xe9ricains ont des imp\xf4ts si simples que le fisc pourrait les faire automatiquement."}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns"}),").\nAu moins 41 % des m\xe9nages am\xe9ricains, soit 62 millions d'unit\xe9s fiscales, pourraient voir leur d\xe9claration d'imp\xf4t enti\xe8rement trait\xe9e par l'IRS par le biais de \"d\xe9clarations pr\xe9-remplies\", sans aucune autre intervention n\xe9cessaire. L'approche la moins conservatrice estime ce chiffre \xe0 73 millions de d\xe9clarations, soit 48 %. Le potentiel des d\xe9clarations automatiques pourrait permettre d'\xe9conomiser du temps et de l'angoisse chaque ann\xe9e, rendant ainsi la saison des imp\xf4ts plus efficace. L'article aborde bri\xe8vement d'autres sujets sans rapport avec les imp\xf4ts, tels que la crise des abus sexuels commis par l'\xc9glise catholique et les cam\xe9ras de Tesla qui font l'objet d'un examen minutieux. Toutefois, il met principalement en avant des solutions uniques \xe0 des probl\xe8mes importants, abord\xe9s dans la lettre d'information Future Perfect. L'article reste neutre et informatif, sans aucun parti pris politique ou religieux."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\nLes imp\xf4ts de 60 millions d'Am\xe9ricains sont suffisamment simples pour que l'IRS les calcule automatiquement. Le moyen le plus facile pour l'IRS de gagner de l'argent est d'auditer les personnes financi\xe8rement vuln\xe9rables. Intuit contribue au ph\xe9nom\xe8ne des lois opaques. L'application des lois par l'IRS \xe9tant limit\xe9e, les Am\xe9ricains \xe0 faibles revenus sont davantage contr\xf4l\xe9s. Les r\xe9centes modifications fiscales r\xe9duisent les possibilit\xe9s de d\xe9ductions d\xe9taill\xe9es. L'IRS ne peut pas maximiser sa capacit\xe9 d'imposition automatique. Le budget de l'IRS a diminu\xe9, puis augment\xe9 r\xe9cemment ; certains pensent que les fonds suppl\xe9mentaires permettront \xe0 l'IRS de maximiser ses recettes au lieu de cibler des personnes sp\xe9cifiques. Proposition de taxer sur la base d'un taux X, de d\xe9poser une d\xe9claration si l'on n'est pas d'accord. Les d\xe9clarations pr\xe9-remplies permettraient d'\xe9conomiser du temps et de l'argent, mais ne sont pas infaillibles. Le lobbying des entreprises contribue \xe0 la complexit\xe9 de l'actuel syst\xe8me fiscal en libre-service. L'automatisation des d\xe9ductions de la taxe sur les ventes pour les transactions en esp\xe8ces n'est pas r\xe9alisable. La pr\xe9paration des d\xe9clarations fiscales fait perdre des milliards de dollars et de temps."]}),"\n",(0,i.jsx)(s.h2,{id:"nous-devons-dire-aux-gens-que-chatgpt-leur-mentira-et-non-pas-d\xe9battre-de-linguistique",children:"Nous devons dire aux gens que ChatGPT leur mentira, et non pas d\xe9battre de linguistique."}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/"}),").\nL'article aborde les questions relatives aux grands mod\xe8les de langage (LLM) tels que ChatGPT, qui peuvent mentir aux gens et pr\xe9sentent des bogues qui r\xe9sistent \xe0 la correction. L'auteur affirme qu'il est plus important d'avertir les gens des risques li\xe9s \xe0 l'utilisation des LLM que de d\xe9battre de la linguistique. Bien que les LLM puissent \xeatre utiles, ils ne sont pas sensibles et on ne peut pas leur faire confiance pour fournir des informations factuelles. L'article soul\xe8ve des questions \xe9thiques sur la n\xe9cessit\xe9 ou non d'encourager les gens \xe0 utiliser les LLM malgr\xe9 leurs d\xe9fauts. L'auteur conclut qu'il est important d'aborder les LLM avec prudence et insiste sur la n\xe9cessit\xe9 d'avertir les gens que les ChatGPT peuvent mentir."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT peut induire les utilisateurs en erreur et il faut leur dire \xe0 plusieurs reprises de ne pas lui faire confiance. Son utilit\xe9 peut \xeatre limit\xe9e si la tendance \xe0 l'hallucination n'est pas r\xe9solue. ChatGPT manque de capacit\xe9s de raisonnement et peut g\xe9n\xe9rer de fausses informations. Certains sont enthousiasm\xe9s par ses avanc\xe9es potentielles, mais d'autres le critiquent pour son manque de capacit\xe9 d'abstraction ou de raisonnement. Le texte g\xe9n\xe9r\xe9 par l'IA doit \xeatre consid\xe9r\xe9 avec scepticisme et comme un assistant bien inform\xe9 mais potentiellement enclin \xe0 la confabulation. Cependant, ChatGPT est utile pour g\xe9n\xe9rer des exemples de code et r\xe9pondre \xe0 des questions complexes. Il offre des r\xe9ponses pr\xe9cises dans 99 % des cas. Les utilisateurs doivent comprendre ses limites afin d'\xe9viter d'attribuer plus de moralit\xe9 que n\xe9cessaire \xe0 ChatGPT."]}),"\n",(0,i.jsx)(s.h2,{id:"twitter-ne-permet-pas-de-retweeter-les-tweets-qui-renvoient-\xe0-substack",children:"Twitter ne permet pas de retweeter les tweets qui renvoient \xe0 Substack"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/"}),").\nTwitter a commenc\xe9 \xe0 restreindre les tweets contenant des liens vers Substack.com en r\xe9ponse \xe0 l'annonce par Substack d'un nouveau produit, Notes, qui concurrencera directement Twitter. Les utilisateurs ont remarqu\xe9 qu'ils ne pouvaient pas retweeter ou r\xe9pondre aux tweets contenant des liens vers Substack, et Twitter a apparemment commenc\xe9 \xe0 bloquer l'insertion de tweets dans les messages de Substack. On pense que cette restriction est une tentative de Twitter de r\xe9duire la port\xe9e d'un rival sur sa plateforme. Twitter a \xe9galement commenc\xe9 \xe0 bloquer les liens vers des plateformes de m\xe9dias sociaux concurrentes en d\xe9cembre 2022. Substack n'a pas encore r\xe9pondu aux questions sur ce sujet."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter a interdit les retweets de tweets contenant des liens vers Substack, estimant que le fait d'aimer ces messages supprimait la discussion. Cette mesure a suscit\xe9 des critiques sur la libert\xe9 d'expression, la position d'Elon Musk \xe0 ce sujet et la concurrence de Substack. Pour certains, Mastodon remplace Twitter. Des discussions sur les relations publiques, l'addiction aux m\xe9dias sociaux et les pratiques douteuses sont abord\xe9es. Aucune nouvelle technologie ou version n'est mentionn\xe9e."]}),"\n",(0,i.jsx)(s.h2,{id:"les-services-cloud-de-western-digital-en-panne-depuis-4-jours",children:"Les services cloud de Western Digital en panne depuis 4 jours"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://status.mycloud.com/os4",children:"Original"}),".\nWestern Digital a connu une panne qui a d\xe9but\xe9 le 2 avril, affectant les services My Cloud, My Cloud Home, SanDisk ibi, et d'autres produits connexes, avec une mise \xe0 jour publi\xe9e le 3 avril. La panne s'est poursuivie jusqu'au 7 avril, affectant l'acc\xe8s aux fichiers et aux applications. Un acc\xe8s local est disponible, permettant aux utilisateurs d'acc\xe9der \xe0 leurs fichiers personnels \xe0 partir d'un ordinateur Windows ou MacOS. D'autres incidents ont eu lieu par le pass\xe9, notamment des probl\xe8mes d'acc\xe8s intermittents, des r\xe9initialisations de mots de passe intermittentes et des probl\xe8mes de connectivit\xe9 intermittents avec des services en nuage. Certains utilisateurs en Chine peuvent \xe9galement rencontrer des probl\xe8mes d'acc\xe8s."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nLes services en nuage de Western Digital sont en panne depuis quatre jours, et les commentaires discutent de la panne et de la garantie de l'entreprise. Certains utilisateurs discutent des limites du mod\xe8le linguistique de GPT et de son mod\xe8le mondial, et s'interrogent sur sa compr\xe9hension de concepts complexes. Les commentaires explorent \xe9galement les termes juridiques entourant la responsabilit\xe9 et les garanties de service des TPG. Les utilisateurs discutent de la valeur des pages d'\xe9tat pendant les pannes, certains sugg\xe9rant des m\xe9thodes alternatives comme le chat. Les utilisateurs d\xe9battent des avantages et des inconv\xe9nients de l'auto-h\xe9bergement, et souhaitent que les m\xe9dias soient accessibles de n'importe o\xf9. Les probl\xe8mes pass\xe9s de Western Digital concernant les disques SMR qui ne sont pas marqu\xe9s de mani\xe8re appropri\xe9e ont amen\xe9 certains utilisateurs \xe0 demander un retour \xe0 des solutions locales."]}),"\n",(0,i.jsx)(s.h2,{id:"comment-fonctionne-le-sharding-des-bases-de-donn\xe9es-",children:"Comment fonctionne le sharding des bases de donn\xe9es ?"}),"\n",(0,i.jsxs)(s.p,{children:["(Original) (",(0,i.jsx)(s.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"https://planetscale.com/blog/how-does-database-sharding-work"}),").\nL'article se penche sur le sharding des bases de donn\xe9es, expliquant les avantages du scaling-out au lieu du scaling-up avec diff\xe9rents sch\xe9mas et algorithmes de sharding discut\xe9s. Il couvre des aspects essentiels tels que l'organisation de l'infrastructure, la cr\xe9ation d'une couche de routage et la planification de la migration, en mettant l'accent sur l'importance de la maintenance. Un bref aper\xe7u des cadres et outils de sharding tels que Vitess et Citus est fourni, CockroachDB inaugurant l'\xe8re des bases de donn\xe9es \"sans serveur\". PlanetScale, un acteur \xe9mergent sur le march\xe9, propose une base de donn\xe9es shard-native construite sur MySQL et Vitess, ainsi que ses ressources d'ing\xe9nierie."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nD\xe9bats sur les avantages et les d\xe9fis du sharding des bases de donn\xe9es ; opter pour un syst\xe8me qui correspond aux donn\xe9es ; le d\xe9bit des touches chaudes est un probl\xe8me dans l'auto-sharding ; alternatives Spanner/Cockroach ou Dynamo/Cassandra ; CockroachDB offre une forte coh\xe9rence et 2PC entre les shards ; les complexit\xe9s de la distribution n\xe9cessitent des services payants ; se concentrer sur l'\xe9volutivit\xe9 horizontale pour \xe9viter d'investir dans une seule machine ; une bonne conception des cl\xe9s peut \xe9viter les points chauds ; le sharding par client est courant ; le sharding multi-tenant est sugg\xe9r\xe9 pour l'\xe9volutivit\xe9 ; Yugabyte, Cockroach et TiDB sont mentionn\xe9s ; le hachage de toutes les donn\xe9es pour la synchronisation n'est pas \xe9volutif ; les escrocs exploitent la pratique de colocalisation des tables d'Amazon ; MongoDB n\xe9cessite un contrat d'assistance aux entreprises."]}),"\n",(0,i.jsx)(s.h2,{id:"hubble-voit-un-possible-trou-noir-en-fuite-cr\xe9ant-une-tra\xeen\xe9e-d\xe9toiles",children:"Hubble voit un possible trou noir en fuite cr\xe9ant une tra\xeen\xe9e d'\xe9toiles"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Original"}),".\nImpossible de g\xe9n\xe9rer un r\xe9sum\xe9 car le texte est un message d'erreur indiquant que la demande n'a pas pu \xeatre satisfaite en raison d'une erreur de configuration ou d'un trafic trop important. Contacter le propri\xe9taire de l'application ou du site web ou consulter la documentation de CloudFront peut aider \xe0 r\xe9soudre le probl\xe8me et \xe0 \xe9viter que cette erreur ne se produise."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),".\nLe t\xe9lescope Hubble a observ\xe9 un trou noir laissant une tra\xeen\xe9e d'\xe9toiles, ce qui a donn\xe9 lieu \xe0 des sp\xe9culations sur son effet sur la vie et sur de nouveaux endroits o\xf9 trouver des plan\xe8tes habitables. Hubble a \xe9galement d\xe9couvert une galaxie rare de type Hoag, d'une taille environ deux fois sup\xe9rieure \xe0 celle de la Voie lact\xe9e. Les scientifiques ont d\xe9couvert un trou noir cr\xe9ant des \xe9toiles \xe0 partir de gaz, ce qui pourrait influencer l'univers et attirer des civilisations avanc\xe9es. Un objet voyageant tr\xe8s rapidement dans l'espace cr\xe9e un impact supersonique sur le gaz, mais l'utilisation du terme \"supersonique\" est probablement m\xe9taphorique. Les utilisateurs de Discussion Service discutent d'histoires de science-fiction telles que Le probl\xe8me \xe0 trois corps, refl\xe9tant des opinions divergentes et recommandant d'autres livres du genre. Les utilisateurs d\xe9battent \xe9galement de la raret\xe9 de la vie sur Terre et du principe d'anthropomorphisme."]}),"\n",(0,i.jsx)(s.h2,{id:"la-plus-grande-violation-de-donn\xe9es-en-nouvelle-z\xe9lande-montre-que-la-r\xe9tention-est-le-g\xe9ant-endormi-de-la-s\xe9curit\xe9-des-donn\xe9es",children:"La plus grande violation de donn\xe9es en Nouvelle-Z\xe9lande montre que la r\xe9tention est le g\xe9ant endormi de la s\xe9curit\xe9 des donn\xe9es."}),"\n",(0,i.jsxs)(s.p,{children:["(Original) (",(0,i.jsx)(s.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/"}),").\nPlus d'un million de permis de conduire et de passeports n\xe9o-z\xe9landais ont \xe9t\xe9 d\xe9couverts dans le cadre de la violation de donn\xe9es de Latitude Financial ; certains dossiers dataient de 18 ans. Le commissaire adjoint \xe0 la protection de la vie priv\xe9e de Nouvelle-Z\xe9lande cite la conservation des donn\xe9es comme un probl\xe8me critique dans les attaques de cybers\xe9curit\xe9, d\xe9clarant que les entreprises et les organisations doivent limiter la collecte et la conservation des donn\xe9es dont elles n'ont pas besoin. Les agences devraient \xe9tablir un calendrier de conservation des informations personnelles, et les individus devraient demander aux organisations auxquelles ils fournissent des informations pourquoi et comment elles sont conserv\xe9es. La protection de la vie priv\xe9e doit devenir une question cruciale pour les entreprises, avec une protection similaire \xe0 celle de la sant\xe9 et de la s\xe9curit\xe9. Latitude Financial contacte tous les clients concern\xe9s pour les informer de la violation et les aider \xe0 r\xe9soudre le probl\xe8me, tout en collaborant avec les autorit\xe9s de r\xe9gulation pour \xe9lucider les d\xe9tails de la violation."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nLa plus importante violation de donn\xe9es en Nouvelle-Z\xe9lande souligne la n\xe9cessit\xe9 de mettre en place des politiques de conservation des donn\xe9es appropri\xe9es ; la suppression devrait \xeatre une priorit\xe9. Le GDPR a fait des progr\xe8s, mais la conservation des donn\xe9es reste omnipr\xe9sente. Les utilisateurs de Discussion Service discutent de la collecte responsable des donn\xe9es, de l'acc\xe8s du gouvernement et de la s\xe9curit\xe9 des donn\xe9es. Les m\xe9thodes de suppression des donn\xe9es et les raisons de leur conservation sont d\xe9battues. Les donn\xe9es personnelles doivent \xeatre minimis\xe9es et trait\xe9es comme des actifs toxiques. Les entreprises doivent \xeatre mieux inform\xe9es sur la confidentialit\xe9 des donn\xe9es."]}),"\n",(0,i.jsx)(s.h2,{id:"les-\xe9tats-unis-et-la-chine-se-livrent-une-guerre-sous-les-vagues-\xe0-propos-des-c\xe2bles-internet",children:"Les \xc9tats-Unis et la Chine se livrent une guerre sous les vagues \xe0 propos des c\xe2bles internet"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/"}),").\nLes \xc9tats-Unis et la Chine s'affrontent au sujet des c\xe2bles sous-marins qui transmettent tout, des courriels aux secrets militaires. Le gouvernement am\xe9ricain est intervenu dans au moins six contrats de c\xe2bles sous-marins priv\xe9s au cours des quatre derni\xe8res ann\xe9es afin d'isoler le secteur chinois de la haute technologie et de limiter l'acc\xe8s de la Chine \xe0 la technologie am\xe9ricaine. La Maison Blanche a r\xe9cemment attribu\xe9 le contrat de c\xe2ble Singapour-France \xe0 la soci\xe9t\xe9 am\xe9ricaine SubCom, plut\xf4t qu'\xe0 la soci\xe9t\xe9 chinoise HMN Tech, pour des raisons de s\xe9curit\xe9. Les efforts agressifs du gouvernement am\xe9ricain pour emp\xeacher l'espionnage chinois par le biais des c\xe2bles sous-marins perturbent les projets des g\xe9ants de la technologie et provoquent des turbulences dans le secteur. La Chine riposte en retardant un projet de c\xe2ble soutenu par Meta, le c\xe2ble Asie du Sud-Est-Japon 2."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),".\nLes \xc9tats-Unis et la Chine se disputent les c\xe2bles internet sous-marins, avec des pr\xe9occupations concernant les fronti\xe8res nationales et la censure. Les retards et les r\xe9acheminements des c\xe2bles ont co\xfbt\xe9 des millions aux g\xe9ants de la technologie. Des experts recommandent des ouvrages sur les infrastructures internationales. Les \xc9tats-Unis s'inqui\xe8tent de l'espionnage chinois et de leur capacit\xe9 \xe0 collecter et \xe0 filtrer le trafic internet. La participation de la Chine au Mouvement des pays non align\xe9s et \xe0 l'initiative \"la Ceinture et la Route\" soul\xe8ve des questions. De nombreuses entreprises sp\xe9cialis\xe9es dans la \"cybers\xe9curit\xe9\" manquent d'ing\xe9nieurs qualifi\xe9s. Le programme de torture de la CIA et l'obligation de rendre compte des crimes de guerre sont abord\xe9s."]}),"\n",(0,i.jsx)(s.h2,{id:"le-sharding-des-bases-de-donn\xe9es-vient-dultima-online-",children:'Le "sharding" des bases de donn\xe9es vient d\'Ultima Online ?'}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Original"}),".\nD\xe9sol\xe9, je ne peux pas g\xe9n\xe9rer de r\xe9sum\xe9 \xe0 partir de ce texte car il s'agit d'un message d'erreur qui n'a rien \xe0 voir avec le sujet donn\xe9."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nLes utilisateurs de Discussion Service discutent de la fa\xe7on dont le "sharding" dans les bases de donn\xe9es a \xe9t\xe9 inspir\xe9 par Ultima Online. Des histoires personnelles racontent comment UO a permis d\'apprendre \xe0 coder. Des affiches \xe9voquent les caract\xe9ristiques du jeu UO et son impact sur la programmation.']}),"\n",(0,i.jsx)(s.h2,{id:"pourquoi-phreesia-a-t-elle-partag\xe9-mes-donn\xe9es-m\xe9dicales-alors-que-je-m\xe9tais-d\xe9sengag\xe9-",children:"Pourquoi Phreesia a-t-elle partag\xe9 mes donn\xe9es m\xe9dicales alors que je m'\xe9tais d\xe9sengag\xe9 ?"}),"\n",(0,i.jsxs)(s.p,{children:["(Original) (",(0,i.jsx)(s.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/"}),").\nUn rapport met en \xe9vidence les entreprises m\xe9dicales qui partagent les donn\xe9es des patients sans leur consentement. Une patiente a refus\xe9 le partage des donn\xe9es, mais Phreesia a tout de m\xeame partag\xe9 ses donn\xe9es. Suggestion d'une r\xe8gle interdisant de faire pression sur le patient pour obtenir son consentement. N\xe9cessit\xe9 d'une option de refus par d\xe9faut afin de rendre l'option de refus claire et facile. Le processus actuel est lourd. Un expert sugg\xe8re de s\xe9parer l'ad tech des soins de sant\xe9. L'auteur est un sociologue ethnographe et un chercheur de donn\xe9es."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia a partag\xe9 les donn\xe9es m\xe9dicales des patients qui se sont retir\xe9s. Nombreux sont ceux qui s'inqui\xe8tent de la confidentialit\xe9 des donn\xe9es et de la responsabilit\xe9, sugg\xe9rant que la publicit\xe9 utilisant des donn\xe9es m\xe9dicales sensibles ne devrait pas \xeatre l\xe9galement autoris\xe9e. Une documentation et des rapports appropri\xe9s doivent \xeatre \xe9tablis pour que ces entreprises soient tenues responsables des violations de la vie priv\xe9e. L'utilisation par les prestataires de soins de sant\xe9 de check-ins \xe9lectroniques et de sch\xe9mas sombres a \xe9t\xe9 critiqu\xe9e. Des lois strictes sur le consentement et l'application de la collecte de donn\xe9es sont n\xe9cessaires aux \xc9tats-Unis. L'app\xe2t du gain des prestataires de soins de sant\xe9 et le ressentiment \xe0 l'\xe9gard des r\xe9glementations relatives \xe0 la confidentialit\xe9 des donn\xe9es des patients sont \xe9galement remis en question."]}),"\n",(0,i.jsx)(s.h2,{id:"javascript-algorithmes--algorithmes-et-structures-de-donn\xe9es-impl\xe9ment\xe9s-en-javascript",children:"JavaScript-algorithmes : Algorithmes et structures de donn\xe9es impl\xe9ment\xe9s en JavaScript"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Original"}),".\nJavaScript-Algorithms est un r\xe9pertoire complet d'algorithmes et de structures de donn\xe9es populaires impl\xe9ment\xe9s en JavaScript, organis\xe9s par th\xe8me et par paradigme. Il convient \xe0 des fins d'apprentissage et de recherche ainsi qu'\xe0 une utilisation en production. Les utilisateurs peuvent trouver des exemples de plusieurs algorithmes et structures de donn\xe9es populaires, y compris des algorithmes de cryptage, d'\xe9volution et d'apprentissage automatique. Le r\xe9f\xe9rentiel contient des explications, la notation Big O et des liens vers des lectures compl\xe9mentaires. Il comprend \xe9galement un terrain de jeu permettant aux lecteurs d'exp\xe9rimenter le code. Des algorithmes avanc\xe9s tels que le branch and bound et la programmation dynamique sont inclus. Les lecteurs doivent noter que les dons sont les bienvenus et que la version 16 ou sup\xe9rieure de Node est requise."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News commente le d\xe9p\xf4t populaire GitHub 'JavaScript-algorithms'. Les utilisateurs discutent de la pertinence du langage pour l'enseignement et l'utilisation pratique, certains mettent en garde contre des comportements inattendus. Certains utilisateurs de Discussion Service critiquent l'impl\xe9mentation des m\xe9thodes 'addBefore()' et 'addAfter()' des listes cha\xeen\xe9es, tandis que d'autres ne sont pas d'accord. Les utilisateurs de Discussion Service recommandent d'autres ressources, critiquent l'efficacit\xe9 des structures de donn\xe9es et soulignent la valeur des ressources pour l'apprentissage des algorithmes."]}),"\n",(0,i.jsx)(s.h2,{id:"spacex-se-rapproche-du-premier-lancement-de-starship-super-heavy",children:"SpaceX se rapproche du premier lancement de Starship Super Heavy"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/"}),").\nSpaceX pr\xe9voit le premier lancement du v\xe9hicule Starship grandeur nature dans le courant du mois d'avril, sous r\xe9serve de l'approbation des autorit\xe9s r\xe9glementaires ; l'Administration f\xe9d\xe9rale de l'aviation a pr\xe9vu une date de lancement le 17 avril, avec des dates de remplacement du 18 au 21 avril, dans son document d'avis sur le plan d'exploitation ; Starship a \xe9t\xe9 enti\xe8rement empil\xe9 sur l'aire de lancement de la base Starbase \xe0 Boca Chica, au Texas, et la soci\xe9t\xe9 pr\xe9voit une r\xe9p\xe9tition de lancement la semaine prochaine, suivie du premier test de vol int\xe9gr\xe9 environ une semaine plus tard. On ne sait pas si Starship entrera en orbite, puis effectuera imm\xe9diatement une mise \xe0 feu de d\xe9sorbitation pour retomber, ou s'il s'agit d'un long vol suborbital."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX s'approche du lancement de Starship Super Heavy, avec des commentaires soulignant son importance pour les voyages spatiaux commerciaux et militaires et un changement de mentalit\xe9. Les contrats gouvernementaux repr\xe9sentent au moins 80 % des revenus de SpaceX. Les fus\xe9es cryog\xe9niques \xe0 carburant liquide de Starship peuvent \xeatre utilis\xe9es pour des missions de dissuasion. Le financement des lancements ne d\xe9pend pas uniquement de la NASA. Une vid\xe9o comparant la taille des fus\xe9es attire l'attention. SpaceX vise provisoirement un lancement le 20 avril. La FAA se pr\xe9occupe de la s\xe9curit\xe9. R\xe9actions mitig\xe9es \xe0 l'attitude irr\xe9v\xe9rencieuse de Musk."]}),"\n",(0,i.jsx)(s.h2,{id:"show-discussion-service--construire-des-synth\xe9tiseurs-musicaux-avec-des-requ\xeates-sql",children:"Show Discussion Service : Construire des synth\xe9tiseurs musicaux avec des requ\xeates SQL"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Original"}),".\nUn d\xe9p\xf4t GitHub appel\xe9 NoiSQL permet de g\xe9n\xe9rer des sons musicaux \xe0 l'aide de requ\xeates SQL, en utilisant des ondes de base, des oscillateurs, des s\xe9quenceurs, des LFO et des g\xe9n\xe9rateurs de bruit. Cr\xe9\xe9s dans un format PCM st\xe9r\xe9o 44,1 kHz 16 bits, les utilisateurs peuvent contr\xf4ler les signaux en d\xe9finissant des fonctions et des expressions en SQL. NoiSQL fournit des instructions et des exemples pour apprendre \xe0 l'utiliser. Le projet peut g\xe9n\xe9rer des notes de musique et des rythmes avec ClickHouse et cr\xe9er diff\xe9rents formats de fichiers. Bien que le projet pr\xe9sente certaines limites, il constitue un moyen innovant d'exp\xe9rimenter les fonctionnalit\xe9s de ClickHouse, et il pourrait \xe9ventuellement s'\xe9tendre \xe0 la g\xe9n\xe9ration de vid\xe9os. Les utilisateurs peuvent apporter de nouveaux exemples au projet."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nUn projet de construction de synth\xe9tiseurs \xe0 l'aide de requ\xeates SQL. Les commentateurs de Discussion Service appr\xe9cient l'id\xe9e unique et mentionnent des projets similaires. Certains utilisateurs notent le manque d'explications et les vuln\xe9rabilit\xe9s potentielles \xe0 l'injection SQL."]}),"\n",(0,i.jsx)(s.h2,{id:"la-plus-longue-ligne-droite-en-grande-bretagne-sans-traverser-de-route-publique",children:"La plus longue ligne droite en Grande-Bretagne sans traverser de route publique"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Original"}),".\nUne ligne droite plus longue que celle identifi\xe9e par Ordnance Survey en 2019 a \xe9t\xe9 trouv\xe9e en Grande-Bretagne sans traverser de route publique. La plus longue ligne droite entre des routes en Grande-Bretagne est \xe9galement la plus longue de tout le Royaume-Uni. Le produit OS Open Roads fournit un grand nombre de donn\xe9es ouvertes, mais il inclut parfois des routes qui ne sont pas publiques. Les routes \xe0 acc\xe8s local restreint sont g\xe9n\xe9ralement des chemins priv\xe9s non pav\xe9s. La ligne la plus longue de Grande-Bretagne se trouve \xe0 l'ouest de l'A9 et non \xe0 l'est. Bien que les donn\xe9es cartographiques soient utiles, elles doivent \xeatre prises avec un grain de sel."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nD\xe9couverte de la plus longue ligne droite de Grande-Bretagne ; il se peut qu'elle ne soit pas parfaitement droite. Quelques discussions sur la distance par rapport aux routes, l'accessibilit\xe9 des chemins de terre et la population. Les utilisateurs mentionnent des r\xe9gions \xe9loign\xe9es dans le monde et la possibilit\xe9 d'automatiser la recherche. Discussion sur l'accord de Schengen et les statistiques relatives aux passeports."]}),"\n",(0,i.jsx)(s.h2,{id:"flipper-zero-interdit-par-amazon-car-il-sagit-dun-dispositif-d\xe9cr\xe9mage-de-cartes",children:"Flipper Zero interdit par Amazon car il s'agit d'un \"dispositif d'\xe9cr\xe9mage de cartes\"."}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/"}),").\nAmazon a interdit la vente du Flipper Zero sur sa plateforme, l'accusant d'\xeatre un \"dispositif d'\xe9cr\xe9mage de cartes\". L'appareil est un outil compact, portable et programmable qui permet d'exp\xe9rimenter et de d\xe9boguer divers appareils num\xe9riques et mat\xe9riels. Les utilisateurs ont pr\xe9sent\xe9 ses capacit\xe9s, ce qui a stimul\xe9 l'interdiction d'Amazon. Certains liens vers des pages d'Amazon pr\xe9c\xe9demment disponibles pour vendre l'outil Flipper Zero sont morts, tandis que d'autres le mentionnent comme \"indisponible\". L'agence nationale br\xe9silienne des t\xe9l\xe9communications a \xe9galement saisi des achats de Flipper Zero en raison de son utilisation pr\xe9sum\xe9e par des criminels. Vous pouvez toujours acheter Flipper Zero sur la boutique officielle du fabricant."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon interdit l'achat du Flipper Zero car il est consid\xe9r\xe9 comme un dispositif d'\xe9cr\xe9mage de cartes, mais il est possible de l'acheter dans la boutique officielle. Les acheteurs le trouvent int\xe9ressant mais pas utile. La politique d'interdiction du Lockpick est incoh\xe9rente et non document\xe9e. Les fabricants du Flipper Zero utilisent une soci\xe9t\xe9 bas\xe9e aux \xc9tats-Unis pour les paiements, ce qui pose des probl\xe8mes de s\xe9curit\xe9. La motivation d'Amazon a \xe9t\xe9 mise en doute pour \xe9viter que les gros titres ne l'associent \xe0 la criminalit\xe9. Flipper Zero a \xe9t\xe9 interdit en raison de son potentiel d'activit\xe9s ill\xe9gales, mais certains avancent des incoh\xe9rences avec les politiques d'Amazon. Certains pensent qu'Amazon pourrait d\xe9velopper sa propre version contrefaite. Flipper Zero a \xe9t\xe9 retir\xe9 d'Amazon et d'eBay mais peut toujours \xeatre achet\xe9 sur le site officiel."]}),"\n",(0,i.jsx)(s.h2,{id:"reverse-engineering-de-lapi-de-facebook-messenger",children:"Reverse Engineering de l'API de Facebook Messenger"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Original"}),".\nL'auteur a proc\xe9d\xe9 \xe0 une r\xe9tro-ing\xe9nierie de l'API Facebook Messenger pour cr\xe9er Messyger, un programme en ligne de commande. L'article explique le processus de connexion et les cookies et propose le code Python sur GitHub. L'accent est mis sur un comportement \xe9thique et des conseils sont donn\xe9s pour effectuer des requ\xeates en dehors du navigateur."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),".\nLes d\xe9veloppeurs d\xe9noncent la lourdeur et l'inefficacit\xe9 de l'API Messenger. La biblioth\xe8que d'applications Facebook a des liens JNI. N\xe9cessit\xe9 de clients tiers, Digital Markets Act cit\xe9. Pr\xe9occupations concernant le spam et la collecte de donn\xe9es, partage d'outils de r\xe9tro-ing\xe9nierie. La r\xe9duction du spam est motiv\xe9e par la recherche du profit, certains soutiennent l'intervention de l'\xc9tat. La r\xe9glementation devrait se concentrer sur les fournisseurs de services en nuage, et non sur les jardins clos. L'utilisateur s'interroge sur la notion de propri\xe9t\xe9 et sur le renflouement des entreprises."]}),"\n",(0,i.jsx)(s.h2,{id:"les-machines-de-tatjana-van-vark",children:"Les machines de Tatjana van Vark"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/"}),").\nTatjana van Vark, chercheuse ind\xe9pendante des Pays-Bas, a construit, reproduit et restaur\xe9 une grande vari\xe9t\xe9 d'instruments scientifiques. Ses projets \xe9labor\xe9s t\xe9moignent d'un superbe savoir-faire et d'un grand souci du d\xe9tail, avec souvent des complexit\xe9s qui vont au-del\xe0 des apparences superficielles. Le travail de Tatjana l'a men\xe9e dans de nombreux domaines d'\xe9tude scientifique, construisant des pi\xe8ces en \xe9lectronique, en optique, en cryptologie, en chimie organique, etc. Malgr\xe9 ses comp\xe9tences de machiniste autodidacte, son atelier contient des machines de haute qualit\xe9 capables de r\xe9pondre aux exigences de son travail de pr\xe9cision. Son travail est de l'artisanat scientifique \xe0 son plus haut niveau, avec des expositions de photos impressionnantes disponibles sur son site web."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nLe travail de Tatjana van Vark est incroyable, et c'est une hackeuse extr\xeame, qui construit des instruments \xe0 partir de rien. Elle poss\xe8de un large \xe9ventail de comp\xe9tences et a produit de nombreuses \u0153uvres qu'il faudrait une vie enti\xe8re pour examiner. La diminution du nombre d'experts est pr\xe9occupante, car la technologie \xe9volue plus vite que nous ne pouvons l'enseigner. Tatjana van Vark et les artisans comme elle n'ont jamais \xe9t\xe9 aussi nombreux."]}),"\n",(0,i.jsx)(s.h2,{id:"big-ball-of-mud-1999",children:"Big Ball of Mud (1999)"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://www.laputan.org/mud/",children:"Original"}),".\nL'article explore l'architecture logicielle BIG BALL OF MUD et les raisons pour lesquelles elle persiste en d\xe9pit d'approches bien pens\xe9es. Sept mod\xe8les sont examin\xe9s, notamment le code jetable et la croissance fragmentaire, ainsi que les causes qui les sous-tendent, telles que les contraintes de temps et la n\xe9gligence de l'architecture. Une architecture pr\xe9matur\xe9e peut entraver l'\xe9volution, et l'inexp\xe9rience ou la rotation du personnel peuvent limiter la sophistication. La programmation en bin\xf4me et les revues de code sont recommand\xe9es pour un examen imm\xe9diat, tandis que le remaniement, la r\xe9paration et la consolidation sont essentiels pour lutter contre la GROSSE BOULE DE BOUE. Il souligne l'importance de la croissance incr\xe9mentale, de la maintenance, de l'adaptation et des tests rigoureux. La reconstruction d'un syst\xe8me peut s'av\xe9rer n\xe9cessaire, mais le remaniement peut offrir une alternative en glanant des \xe9l\xe9ments architecturaux dans le syst\xe8me actuel."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),".\nL'article \"Big Ball of Mud (1999)\" est un document tr\xe8s appr\xe9ci\xe9 sur le g\xe9nie logiciel. Plusieurs utilisateurs font l'\xe9loge de sa perspicacit\xe9 et de sa pertinence, le citant comme une explication compl\xe8te de ce que l'on voit chaque semaine dans des situations r\xe9elles. D'autres citent d'autres articles aussi importants ou des d\xe9veloppements ult\xe9rieurs dans le domaine de l'ing\xe9nierie logicielle, tels que les microservices. Certains utilisateurs commentent leurs exp\xe9riences personnelles en rapport avec l'article. Enfin, certains utilisateurs critiquent la mise en forme de l'article ou signalent qu'il a d\xe9j\xe0 \xe9t\xe9 publi\xe9."]}),"\n",(0,i.jsx)(s.h2,{id:"yann-lecun-et-andrew-ng--pourquoi-la-pause-de-6-mois-sur-lia-est-une-mauvaise-id\xe9e-vid\xe9o",children:"Yann LeCun et Andrew Ng : Pourquoi la pause de 6 mois sur l'IA est une mauvaise id\xe9e [vid\xe9o]"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Original"}),".\nIl ne s'agit pas du contenu r\xe9el de l'article. Veuillez me fournir le texte pour que je puisse le r\xe9sumer."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun et Andrew Ng critiquent la pause de 6 mois dans l'IA, sugg\xe9rant qu'elle est irr\xe9aliste et donne un avantage \xe0 l'OpenAI. Les d\xe9bats sur l'hiver de l'IA, la repr\xe9sentation de la pens\xe9e humaine et les perturbations soci\xe9tales sont mis en \xe9vidence. Les progr\xe8s de l'IA offrent des capacit\xe9s inattendues au-del\xe0 du texte et suscitent des inqui\xe9tudes quant \xe0 la perte d'emplois et \xe0 la pauvret\xe9. Les experts ont des avis partag\xe9s sur l'efficacit\xe9 de la pause dans le d\xe9veloppement de l'IA et sur les risques d'une IA non r\xe9glement\xe9e. La menace potentielle d'une intelligence artificielle surpassant l'intelligence humaine et les technologies de surveillance par apprentissage profond sont \xe9voqu\xe9es, de m\xeame que les pr\xe9occupations concernant l'alignement de l'IA sur les objectifs humains."]}),"\n",(0,i.jsx)(s.h2,{id:"la-nsa-a-cr\xe9\xe9-un-cours-de-cybers\xe9curit\xe9-en-ligne-avec-des-centaines-de-classes",children:"La NSA a cr\xe9\xe9 un cours de cybers\xe9curit\xe9 en ligne avec des centaines de classes"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://clark.center/c/nccp",children:"https://clark.center/c/nccp"}),").\nLa NSA a cr\xe9\xe9 un cours de cybers\xe9curit\xe9 en ligne avec des centaines de classes disponibles. Ce cours, appel\xe9 CLARK, couvre un large \xe9ventail de sujets, notamment la s\xe9curit\xe9 des r\xe9seaux, la cryptographie et les cybermenaces. Les cours s'adressent aussi bien aux d\xe9butants qu'aux experts et sont accessibles gratuitement \xe0 toute personne disposant d'une connexion internet. Le cours a suscit\xe9 une certaine controverse, certains critiques affirmant qu'il constitue une porte d\xe9rob\xe9e permettant \xe0 la NSA d'acc\xe9der \xe0 des informations priv\xe9es. La NSA a toutefois d\xe9menti ces all\xe9gations et affirme que le cours est purement \xe9ducatif."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nLa NSA a cr\xe9\xe9 un cours de cybers\xe9curit\xe9, mais l'utilisation par l'agence d'exploits 0day dans le cadre d'op\xe9rations offensives suscite des inqui\xe9tudes. Certains utilisateurs notent que la s\xe9paration entre l'attaque et la d\xe9fense est moins inqui\xe9tante qu'il n'y para\xeet. Le cours fait partie du syst\xe8me CLARK, qui est partiellement financ\xe9 par la NSA, mais qui est principalement g\xe9r\xe9 par l'universit\xe9 de Towson. Certains utilisateurs critiquent le manque de couverture de certains sujets dans le cours."]}),"\n",(0,i.jsx)(s.h2,{id:"remplacer-les-mauvais-syst\xe8mes-par-dautres-mauvais-syst\xe8mes",children:"Remplacer les mauvais syst\xe8mes par d'autres mauvais syst\xe8mes"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Original"}),".\nDans son billet de blog, Seth utilise la m\xe9taphore des parcm\xe8tres obsol\xe8tes pour illustrer la n\xe9cessit\xe9 de repenser et d'am\xe9liorer les mauvais syst\xe8mes. Bien que leur remplacement puisse sembler co\xfbteux, les syst\xe8mes centralis\xe9s comme l'application Parkmobile ont souvent leurs propres d\xe9fauts. Pour en revenir \xe0 l'objectif initial, qui est de g\xe9n\xe9rer des revenus et d'emp\xeacher le stationnement toute la journ\xe9e, M. Seth sugg\xe8re de mettre en place une application gratuite qui permet de scanner un code pour autoriser une p\xe9riode de stationnement. Un service de paiement en ligne ou la vente de cartes de stationnement avec diff\xe9rentes options de r\xe9duction sont d'autres options permettant d'augmenter les revenus. Bien qu'il soit difficile de faire des choix UX pour un syst\xe8me public, les syst\xe8mes distribu\xe9s comme WordPress ont prosp\xe9r\xe9 gr\xe2ce \xe0 leur conception d\xe9centralis\xe9e et conviviale. Le principal avantage des syst\xe8mes distribu\xe9s est leur capacit\xe9 \xe0 s'am\xe9liorer au fil du temps, plut\xf4t que de se calcifier comme les syst\xe8mes centralis\xe9s. Pour aller de l'avant, Seth sugg\xe8re que nous donnions la priorit\xe9 \xe0 de meilleures solutions plut\xf4t qu'\xe0 davantage de solutions."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nAu Danemark, un syst\xe8me de stationnement plus simple utilise des cadrans manuels et pr\xe9voit des amendes pour les tricheurs. Les utilisateurs signalent des syst\xe8mes similaires \xe0 l'\xe9tranger. Des solutions complexes sont souvent utilis\xe9es en d\xe9pit d'options simples. Les parcm\xe8tres de Chicago ont g\xe9n\xe9r\xe9 200 millions de dollars en 10 ans. Les nouveaux parcm\xe8tres \xe9lectroniques sont moins pratiques que les classiques. Les gouvernements se d\xe9battent avec les syst\xe8mes de paiement, qu'ils laissent parfois aux vendeurs. Les parcm\xe8tres sont principalement utilis\xe9s pour l'argent, mais ils emp\xeachent \xe9galement le stationnement toute la journ\xe9e. Selon un commentateur, l'article n'a pas d'int\xe9r\xeat, tandis qu'un autre critique l'auteur."]}),"\n",(0,i.jsx)(s.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Original"}),".\nLa version 0.9.0 de Neovim a \xe9t\xe9 publi\xe9e, avec des changements pour iconv, libintl, optional params, lua2dox, semantic tokens, '+tui', le support des modules de n\u0153uds Yarn, et la mise en \xe9vidence des blocs de code. La version 8.2.2902 de Vim a \xe9galement \xe9t\xe9 publi\xe9e avec des corrections de bogues et une am\xe9lioration de la prise en charge des scripts Lua et des LSP. La derni\xe8re version de Neovim pr\xe9sente de nouvelles fonctionnalit\xe9s int\xe9ressantes et des am\xe9liorations de stabilit\xe9, tandis que Vim se concentre sur les corrections de bogues et l'am\xe9lioration des fonctionnalit\xe9s. Les mises \xe0 jour de Neovim comprennent des am\xe9liorations de 'treesitter', 'tui' et 'windows', des correctifs logiciels \xe0 une documentation am\xe9lior\xe9e, rationalisant l'exp\xe9rience de Neovim et consolidant sa position en tant que logiciel performant et convivial. D'autres mises \xe0 jour incluent des changements dans la fonction 'expect_unchanged()', EditorConfig et la coloration syntaxique pour les fichiers d'aide, une instance sans t\xeate, des capacit\xe9s am\xe9lior\xe9es pour le client LSP, et le support des plugins pour les interfaces graphiques."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 d\xe9pr\xe9cie 'exrc' et ajoute une \"base de donn\xe9es de confiance\". Les experts recommandent appImage ou .local pour l'installation. Le support de EditorConfig est maintenant int\xe9gr\xe9. D\xe9bat sur les m\xe9rites de Neovim, alors que certains critiquent la fragmentation, d'autres sugg\xe8rent des gestionnaires de plugins. Neovim permet de nouveaux outils et plugins. Lua pr\xe9sente des avantages pour le d\xe9veloppement de plugins. Helix Editor dispose d'un mod\xe8le objet-verbe, d'un serveur de langage \xe0 configuration nulle et d'un tuteur. Sa s\xe9lection est moins flexible, mais les utilisateurs ne tarissent pas d'\xe9loges sur sa facilit\xe9 d'utilisation et son efficacit\xe9."]}),"\n",(0,i.jsx)(s.h2,{id:"ask-discussion-service--quelle-est-votre-meilleure-ressource-pour-vous-tenir-au-courant-des-d\xe9veloppements-en-mati\xe8re-dia-",children:"Ask Discussion Service : Quelle est votre meilleure ressource pour vous tenir au courant des d\xe9veloppements en mati\xe8re d'IA ?"}),"\n",(0,i.jsx)(s.p,{children:"N/A (Comme il s'agit d'instructions g\xe9n\xe9rales pour r\xe9sumer, il n'y a pas de texte \xe0 r\xe9sumer)."}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service recommandent des ressources pour se tenir au courant des d\xe9veloppements de l'IA, y compris le site web Papers with Code, les blogs et les bulletins d'information. La prudence est de mise en raison de la surcharge d'informations. Certains proposent des ressources pour les d\xe9butants. Les r\xe9centes avanc\xe9es dans le domaine de l'IA, y compris les innovations mat\xe9rielles et algorithmiques, ont permis d'am\xe9liorer l'entra\xeenement des grands r\xe9seaux neuronaux et d'atteindre des performances de niveau humain. Le d\xe9bat se poursuit sur les perc\xe9es r\xe9volutionnaires."]}),"\n",(0,i.jsx)(s.h2,{id:"preuve-directe-de-lutilisation-de-drogues-multiples-\xe0-l\xe2ge-du-bronze-\xe0-partir-dun-test-sur-des-cheveux-humains",children:"Preuve directe de l'utilisation de drogues multiples \xe0 l'\xe2ge du bronze \xe0 partir d'un test sur des cheveux humains"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nUne \xe9tude a trouv\xe9 des preuves directes de l'utilisation de plusieurs esp\xe8ces de plantes psychoactives \xe0 Minorque, \xe0 l'\xe2ge du bronze, gr\xe2ce \xe0 l'analyse de cheveux humains. Les cheveux contenaient de l'\xe9ph\xe9drine, de l'atropine et de la scopolamine. Les arch\xe9ologues d\xe9duisent g\xe9n\xe9ralement l'utilisation de substances psychotropes \xe0 partir d'artefacts, mais cette analyse est directe. Cette d\xe9couverte jette un nouvel \xe9clairage sur la consommation de drogues dans les soci\xe9t\xe9s anciennes, indiquant des connaissances sp\xe9cialis\xe9es et un usage chamanique potentiel. L'\xe9tude r\xe9v\xe8le l'importance de comprendre le r\xf4le des plantes psychoactives et de la consommation de drogues dans les cultures du pass\xe9. De nombreuses \xe9tudes montrent des preuves de l'utilisation de plantes psychoactives dans les cultures anciennes, mettant en \xe9vidence la longue histoire de la consommation de drogues par l'homme."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nDes tests capillaires r\xe9v\xe8lent la pr\xe9sence de drogues \xe0 l'\xe2ge du bronze, avec de multiples esp\xe8ces psychoactives. Les commentaires discutent des impacts soci\xe9taux de la consommation de drogues, des choix personnels, de l'\xe9ducation et des valeurs. L'interdiction des drogues est ancr\xe9e dans la sant\xe9 publique, la moralit\xe9 et le racisme. L'article neutre \xe9vite les pr\xe9jug\xe9s politiques et les sp\xe9culations."]}),"\n",(0,i.jsx)(s.h2,{id:"des-officiers-de-la-police-de-new-york-se-vantent-de-faire-des-heures-suppl\xe9mentaires-dans-un-enregistrement-accidentel",children:"Des officiers de la police de New York se vantent de faire des heures suppl\xe9mentaires dans un enregistrement accidentel"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording"}),").\nUn enregistrement accidentel r\xe9alis\xe9 lors de l'arrestation d'un ouvrier du b\xe2timent a r\xe9v\xe9l\xe9 que des policiers se vantaient d'avoir \"profit\xe9 des heures suppl\xe9mentaires\" et utilisaient un langage d\xe9sobligeant \xe0 l'\xe9gard des d\xe9tenus. L'enregistrement met en lumi\xe8re la fa\xe7on dont les r\xe9centes r\xe9formes de la justice p\xe9nale ont eu un impact sur la mani\xe8re dont les officiers traitent les arrestations et per\xe7oivent les heures suppl\xe9mentaires. Il semblerait que les policiers profitent des changements apport\xe9s aux lois sur la lib\xe9ration sous caution et la d\xe9couverte pour accumuler des heures suppl\xe9mentaires. La police de New York a refus\xe9 de commenter l'enregistrement, qui contient \xe9galement des commentaires insensibles faits par des officiers sur les d\xe9tenus."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nLes agents de la police de New York se vantent d'accumuler des heures suppl\xe9mentaires, mais l'article r\xe9v\xe8le qu'ils utilisent des insultes, des plaisanteries sur l'institutionnalisation des personnes, etc. Certains pensent que les forces de l'ordre aux \xc9tats-Unis sont confront\xe9es \xe0 des probl\xe8mes bien plus graves et que les heures suppl\xe9mentaires de la police ne sont qu'un leurre. D'autres estiment que l'exploitation des heures suppl\xe9mentaires en prolongeant la d\xe9tention est anticonstitutionnelle et m\xe9rite des poursuites pour crime. La corruption des forces de police a conduit \xe0 des appels \xe0 leur abolition et \xe0 leur remplacement. L'absence de surveillance et de contr\xf4les ad\xe9quats permet d'exploiter les heures suppl\xe9mentaires et de commettre des malversations. Le comportement des personnes arm\xe9es et b\xe9n\xe9ficiant d'un traitement pr\xe9f\xe9rentiel en vertu de la loi suscite des inqui\xe9tudes."]}),"\n",(0,i.jsx)(s.h2,{id:"show-discussion-service--chatgdb---gpt-powered-gdb-assistant",children:"Show Discussion Service : ChatGDB - GPT-Powered GDB Assistant"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://github.com/pgosar/ChatGDB",children:"Original"}),".\nChatGDB est un outil qui am\xe9liore l'exp\xe9rience de d\xe9bogage dans GDB en utilisant la puissance de ChatGPT, permettant aux commandes en langage naturel d'\xeatre ex\xe9cut\xe9es automatiquement. Les utilisateurs peuvent \xe9galement demander \xe0 ChatGPT d'expliquer la commande qui vient d'\xeatre ex\xe9cut\xe9e ou m\xeame lui poser une question. Pour l'installer, Python version 3.3 ou sup\xe9rieure et pip doivent \xeatre install\xe9s, suivis de la commande ",(0,i.jsx)(s.code,{children:"pip3 install chatgdb"})," et de la cr\xe9ation d'un ex\xe9cutable avec ",(0,i.jsx)(s.code,{children:"chatgdb -k <API KEY>"}),". L'outil peut \xeatre utilis\xe9 dans GDB en tapant ",(0,i.jsx)(s.code,{children:"chat"})," suivi de la commande d\xe9sir\xe9e, et la commande ",(0,i.jsx)(s.code,{children:"explain"})," peut \xeatre utilis\xe9e pour demander une explication de la commande pr\xe9c\xe9dente ou pour poser une question."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),".\nChatGDB est un assistant GDB aliment\xe9 par GPT, am\xe9liorant les flux de travail de d\xe9bogage. L'utilisateur de Discussion Service note que le code du programme est minimal. ChatGPT acc\xe9l\xe8re la compr\xe9hension de l'utilisateur pour les technologies peu famili\xe8res, les t\xe2ches de refactorisation. La version CLI de ChatGPT est sugg\xe9r\xe9e. ChatGPT acc\xe9l\xe8re les flux de travail, malgr\xe9 la pr\xe9f\xe9rence de certains utilisateurs pour la m\xe9moire musculaire. ChatGPT-3 pr\xe9sente une invite en langage naturel pour GDB, utile pour les \"fuites de m\xe9moire et les d\xe9fauts de segmentation\". L'interface reste difficile \xe0 manier dans certains sc\xe9narios, mais la police de caract\xe8res et la palette de couleurs sont bien accueillies."]})]})}function c(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);